     8	
     9	// These three bounds mirror what the server enforces. Checking the picked file
    10	// first keeps a mistaken choice off the wire instead of uploading twenty
    11	// megabytes only to be told the extension is wrong.
    12	export const MAX_GUIDE_DOCUMENT_BYTES = 20 * 1024 * 1024;
    13	export const MAX_GUIDE_DOCUMENTS = 10;
    14	export const GUIDE_DOCUMENT_EXTENSIONS = [
    15	  ".pdf",
    16	  ".md",
    17	  ".markdown",
    18	  ".txt",
    19	  ".csv",
    20	  ".doc",
    21	  ".docx",
    22	  ".ppt",
    23	  ".pptx",
    24	  ".xls",
    25	  ".xlsx",
    26	  ".hwp",
    27	  ".hwpx",
    28	];
    29	export const GUIDE_DOCUMENT_ACCEPT = GUIDE_DOCUMENT_EXTENSIONS.join(",");
    30	
    31	export function formatFileSize(bytes: number): string {
    32	  if (!Number.isFinite(bytes) || bytes <= 0) return "0 KB";
    33	  if (bytes < 1024) return `${bytes} B`;
    34	  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
    35	  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    36	}
    37	
    38	export function guideDocumentError(
    39	  file: File,
    40	  alreadyAttached: number,
    41	): string {
    42	  const extension = file.name.slice(file.name.lastIndexOf(".")).toLowerCase();
    43	  if (
    44	    !file.name.includes(".") ||
    45	    !GUIDE_DOCUMENT_EXTENSIONS.includes(extension)
    46	  )
    47	    return `${file.name}: PDF, Markdown, 텍스트, CSV, Word, PowerPoint, Excel, 한글 문서만 첨부할 수 있습니다.`;
    48	  if (file.size === 0) return `${file.name}: 빈 파일은 첨부할 수 없습니다.`;
    49	  if (file.size > MAX_GUIDE_DOCUMENT_BYTES)
    50	    return `${file.name}: 가이드 문서는 20MB 이하여야 합니다.`;
    51	  if (alreadyAttached >= MAX_GUIDE_DOCUMENTS)
    52	    return `가이드 문서는 앱당 ${MAX_GUIDE_DOCUMENTS}개까지 첨부할 수 있습니다.`;
    53	  return "";
    54	}
    55	
    56	export interface GuideDocumentDraft {
    57	  /** Documents already stored for the app; empty while the app is being created. */
    58	  stored: AppDocument[];
    59	  storedError: Error | null;
    60	  /** Files picked in this form and not uploaded yet. */
    61	  pending: File[];
    62	  /** Stored documents marked for removal on the next save. */
    63	  removed: string[];
    64	  pickError: string;
    65	  applying: boolean;
    66	  applyError: Error | null;
    67	  add: (files: FileList | null) => void;
    68	  dropPending: (index: number) => void;
    69	  toggleRemoved: (id: string) => void;
    70	  /** Applies the staged removals and uploads. Called after the app is saved. */
    71	  apply: (appId: string) => Promise<void>;
    72	}
    73	
    74	/**
    75	 * Staging area for an app form's guide attachments.
    76	 *
    77	 * Uploading on pick would need an app that does not exist yet on the register
    78	 * screen, and would leave a half-attached app behind if the form is abandoned.
    79	 * So both the additions and the removals wait here until the form is saved and
    80	 * the app has an identifier; `apply` then replays them in one go.
    81	 */
    82	export function useGuideDocumentDraft(appId?: string): GuideDocumentDraft {
    83	  const client = useQueryClient();
    84	  const [pending, setPending] = useState<File[]>([]);
    85	  const [removed, setRemoved] = useState<string[]>([]);
    86	  const [pickError, setPickError] = useState("");
    87	  const stored = useQuery({
    88	    queryKey: ["app-documents", appId],
    89	    queryFn: ({ signal }) => api.appDocuments(appId ?? "", signal),
    90	    enabled: !!appId,
    91	  });
    92	  const documents = stored.data ?? [];
    93	
    94	  const apply = useMutation({
    95	    mutationFn: async (targetAppId: string) => {
    96	      for (const id of removed) await api.deleteAppDocument(targetAppId, id);
    97	      for (const file of pending)
    98	        await api.uploadAppDocument(targetAppId, file);
    99	      setPending([]);
   100	      setRemoved([]);
   101	      await client.invalidateQueries({ queryKey: ["app-documents"] });
   102	    },
   103	  });
   104	
   105	  return {
   106	    stored: documents,
   107	    storedError: stored.error,
   108	    pending,
   109	    removed,
   110	    pickError,
   111	    applying: apply.isPending,
   112	    applyError: apply.error,
   113	    add: (files) => {
   114	      const picked = [...(files ?? [])];
   115	      if (!picked.length) return;
   116	      // One name per app is what the server stores, so a name already taken
   117	      // is refused here rather than on a save that would fail halfway.
   118	      const taken = new Set(
   119	        documents
   120	          .filter((document) => !removed.includes(document.id))
   121	          .map((document) => document.fileName.toLowerCase())
   122	          .concat(pending.map((file) => file.name.toLowerCase())),
   123	      );
   124	      let attached = documents.length - removed.length + pending.length;
   125	      const accepted: File[] = [];
   126	      let error = "";
   127	      let rejected = 0;
   128	      for (const file of picked) {
   129	        const failure = taken.has(file.name.toLowerCase())
   130	          ? file.name + ": 같은 이름의 문서가 이미 있습니다."
   131	          : guideDocumentError(file, attached);
   132	        if (failure) {
   133	          if (!error) error = failure;
   134	          rejected += 1;
   135	          continue;
   136	        }
   137	        taken.add(file.name.toLowerCase());
   138	        accepted.push(file);
   139	        attached += 1;
   140	      }
   141	      setPickError(
   142	        rejected > 1 ? `${error} (총 ${rejected}개 파일 첨부 실패)` : error,
   143	      );
   144	      if (accepted.length) setPending((current) => [...current, ...accepted]);
   145	    },
   146	    dropPending: (index) => {
   147	      setPickError("");
   148	      setPending((current) => current.filter((_, at) => at !== index));
   149	    },
   150	    toggleRemoved: (id) =>
   151	      setRemoved((current) =>
   152	        current.includes(id)
   153	          ? current.filter((item) => item !== id)
   154	          : [...current, id],
   155	      ),
   156	    apply: async (targetAppId: string) => {
   157	      if (!removed.length && !pending.length) return;
   158	      await apply.mutateAsync(targetAppId);
   159	    },
   160	  };
   161	}
